public void test_getRunningQueries_selfOnly_regularUser() {
    Mockito.when(httpServletRequest.getAttribute(AuthConfig.DRUID_AUTHENTICATION_RESULT)).thenReturn(makeAuthenticationResult(REGULAR_USER_NAME));
    final ControllerHolder holder = setUpMockRunningQuery(REGULAR_USER_NAME);
    final ControllerHolder holder2 = setUpMockRunningQuery(DIFFERENT_REGULAR_USER_NAME);
    // Regular users can see only their own queries, without authentication details.
    Assertions.assertEquals(2, controllerRegistry.getAllControllers().size());
    Assertions.assertEquals(new GetQueriesResponse(Collections.singletonList(DartQueryInfo.fromControllerHolder(holder).withoutAuthenticationResult())), sqlResource.doGetRunningQueries("", null, httpServletRequest).getEntity());
    controllerRegistry.deregister(holder, null);
    controllerRegistry.deregister(holder2, null);
}

