/**
 * Test where a superuser calls {@link SqlResource#doGetRunningQueries} with selfOnly disabled.
 */
@Test
public void test_getRunningQueries_global_superUser() {
    Mockito.when(httpServletRequest.getAttribute(AuthConfig.DRUID_AUTHENTICATION_RESULT)).thenReturn(makeAuthenticationResult(CalciteTests.TEST_SUPERUSER_NAME));
    // REGULAR_USER_NAME runs a query locally.
    final ControllerHolder localHolder = setUpMockRunningQuery(REGULAR_USER_NAME);
    // DIFFERENT_REGULAR_USER_NAME runs a query remotely.
    final DartQueryInfo remoteQueryInfo = new DartQueryInfo("sid", "did2", "SELECT 2", "localhost:1002", AUTHENTICATOR_NAME, DIFFERENT_REGULAR_USER_NAME, DateTimes.of("2001"), StandardQueryState.RUNNING, null);
    Mockito.when(dartSqlClient.getQueries(true, false)).thenReturn(Futures.immediateFuture(new GetQueriesResponse(Collections.singletonList(remoteQueryInfo))));
    // With selfOnly = null, the endpoint returns both queries.
    Assertions.assertEquals(new GetQueriesResponse(ImmutableList.of(DartQueryInfo.fromControllerHolder(localHolder), remoteQueryInfo)), sqlResource.doGetRunningQueries(null, null, httpServletRequest).getEntity());
    controllerRegistry.deregister(localHolder, null);
}

