    final String dataSource = DATA_SOURCE_PREFIX + 0;
    compactionConfigs.add(InlineSchemaDataSourceCompactionConfig.builder().forDataSource(dataSource).withTaskPriority(0).withInputSegmentSizeBytes(500L).withSkipOffsetFromLatest(// smaller than segment interval
