private CoordinatorSegmentMetadataCache setupForColdDatasourceSchemaTest(ServiceEmitter emitter) {
    // foo has both hot and cold segments
    final String fingerprint1 = "fingerprint-1";
    final String fingerprint2 = "fingerprint-2";
    DataSegment coldSegment = DataSegment.builder().dataSource(DATASOURCE1).interval(Intervals.of("1998/P2Y")).version("1").shardSpec(new LinearShardSpec(0)).size(0).build();
    // cold has only cold segments
    DataSegment singleColdSegment = DataSegment.builder().dataSource("cold").interval(Intervals.of("2000/P2Y")).version("1").shardSpec(new LinearShardSpec(0)).size(0).build();
    ImmutableMap.Builder<SegmentId, SegmentMetadata> segmentStatsMap = new ImmutableMap.Builder<>();
    segmentStatsMap.put(coldSegment.getId(), new SegmentMetadata(20L, fingerprint1));
    segmentStatsMap.put(singleColdSegment.getId(), new SegmentMetadata(20L, fingerprint2));
    ImmutableMap.Builder<String, SchemaPayload> schemaPayloadMap = new ImmutableMap.Builder<>();
    schemaPayloadMap.put(fingerprint1, new SchemaPayload(RowSignature.builder().add("dim1", ColumnType.STRING).add("c1", ColumnType.STRING).add("c2", ColumnType.LONG).build()));
    schemaPayloadMap.put(fingerprint2, new SchemaPayload(RowSignature.builder().add("f1", ColumnType.STRING).add("f2", ColumnType.DOUBLE).build()));
    segmentSchemaCache.resetSchemaForPublishedSegments(segmentStatsMap.build(), schemaPayloadMap.build());
    Mockito.when(segmentsMetadataManager.getRecentDataSourcesSnapshot()).thenReturn(DataSourcesSnapshot.fromUsedSegments(List.of(segment1, segment2, coldSegment, singleColdSegment)));
    CoordinatorSegmentMetadataCache schema = new CoordinatorSegmentMetadataCache(getQueryLifecycleFactory(walker), serverView, SEGMENT_CACHE_CONFIG_DEFAULT, new NoopEscalator(), new InternalQueryConfig(), emitter, segmentSchemaCache, backFillQueue, segmentsMetadataManager, segmentsMetadataManagerConfigSupplier);
    SegmentReplicaCount zeroSegmentReplicaCount = Mockito.mock(SegmentReplicaCount.class);
    SegmentReplicaCount nonZeroSegmentReplicaCount = Mockito.mock(SegmentReplicaCount.class);
    Mockito.when(zeroSegmentReplicaCount.required()).thenReturn(0);
    Mockito.when(nonZeroSegmentReplicaCount.required()).thenReturn(1);
    SegmentReplicationStatus segmentReplicationStatus = Mockito.mock(SegmentReplicationStatus.class);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(coldSegment.getId()))).thenReturn(zeroSegmentReplicaCount);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(singleColdSegment.getId()))).thenReturn(zeroSegmentReplicaCount);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(segment1.getId()))).thenReturn(nonZeroSegmentReplicaCount);
    Mockito.when(segmentReplicationStatus.getReplicaCountsInCluster(ArgumentMatchers.eq(segment2.getId()))).thenReturn(nonZeroSegmentReplicaCount);
    schema.updateSegmentReplicationStatus(segmentReplicationStatus);
    schema.updateSegmentReplicationStatus(segmentReplicationStatus);
    return schema;
}

