    query = new ClientSqlQuery("SELECT TIME_PARSE(ts) AS __time, c1 FROM (VALUES('2023-01-01', 'insert_1'), ('2023-01-01', 'insert_2'), ('2023-02-01', 'insert3')) AS t(ts, c1) PARTITIONED BY ALL ", null, false, false, false, null, null);
    Mockito.when(brokerClient.fetchExplainPlan(query)).thenReturn(Futures.immediateFuture(ImmutableList.of(new ExplainPlan("", "", new ExplainAttributes("SELECT", null, null, null, null)))));
    MatcherAssert.assertThat(assertThrows(DruidException.class, () -> new ScheduledBatchSupervisorSpec(query, new UnixCronSchedulerConfig("* * * * *"), true, null, null, OBJECT_MAPPER, scheduler, brokerClient)), DruidExceptionMatcher.invalidInput().expectMessageIs("SELECT queries are not supported by the [scheduled_batch] supervisor. Only INSERT or REPLACE ingest queries are allowed."));
}

