@Test
public void testParseMalformedDataWithAllowedParseExceptions_thenNoException() throws IOException {
    final int maxAllowedParseExceptions = 1;
    final StreamChunkReader<ByteEntity> chunkParser = new StreamChunkReader<>(mockedByteEntityReader, InputRowFilter.allowAll(), rowIngestionMeters, new ParseExceptionHandler(rowIngestionMeters, false, maxAllowedParseExceptions, 0));
    Mockito.when(mockedByteEntityReader.read()).thenThrow(new ParseException(null, "error parsing malformed data"));
    final String json = "malformedJson";
    List<InputRow> parsedRows = chunkParser.parse(Collections.singletonList(new ByteEntity(json.getBytes(StringUtils.UTF8_STRING))), false);
    // no exception and no parsed rows
    Assert.assertEquals(0, parsedRows.size());
    Assert.assertEquals(maxAllowedParseExceptions, rowIngestionMeters.getUnparseable());
}

@Test
public void testParseMalformedDataException() throws IOException {
    final StreamChunkReader<ByteEntity> chunkParser = new StreamChunkReader<>(mockedByteEntityReader, InputRowFilter.allowAll(), rowIngestionMeters, parseExceptionHandler);
    Mockito.when(mockedByteEntityReader.read()).thenThrow(new ParseException(null, "error parsing malformed data"));
    final String json = "malformedJson";
    List<ByteEntity> byteEntities = Arrays.asList(new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)));
    Assert.assertThrows("Max parse exceptions[0] exceeded", RE.class, () -> chunkParser.parse(byteEntities, false));
    // should barf on the first unparseable row
    Assert.assertEquals(1, rowIngestionMeters.getUnparseable());
}

@Test
public void testParseMalformedDataWithUnlimitedAllowedParseExceptions_thenNoException() throws IOException {
    final StreamChunkReader<ByteEntity> chunkParser = new StreamChunkReader<>(mockedByteEntityReader, InputRowFilter.allowAll(), rowIngestionMeters, new ParseExceptionHandler(rowIngestionMeters, false, Integer.MAX_VALUE, 0));
    Mockito.when(mockedByteEntityReader.read()).thenThrow(new ParseException(null, "error parsing malformed data"));
    final String json = "malformedJson";
    List<ByteEntity> byteEntities = Arrays.asList(new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)), new ByteEntity(json.getBytes(StringUtils.UTF8_STRING)));
    List<InputRow> parsedRows = chunkParser.parse(byteEntities, false);
    // no exception since we've unlimited threhold for parse exceptions
    Assert.assertEquals(0, parsedRows.size());
    Assert.assertEquals(byteEntities.size(), rowIngestionMeters.getUnparseable());
}

