@Mock
private TimelineServerView serverView;

locationContext.methodRawCode:
@BeforeEach
void setUp() {
    mockCloser = MockitoAnnotations.openMocks(this);
    slicer = DartTableInputSpecSlicer.createFromWorkerIds(WORKER_IDS, serverView, QueryContext.empty());
    // Add all segments to the timeline, round-robin across the two servers.
    timeline = new VersionedIntervalTimeline<>(Ordering.natural());
    for (Map.Entry<DataSegment, IntList> entry : SEGMENT_SERVERS.entrySet()) {
        final DataSegment dataSegment = entry.getKey();
        final IntList segmentServers = entry.getValue();
        final ServerSelector serverSelector = new ServerSelector(dataSegment, new HighestPriorityTierSelectorStrategy(new RandomServerSelectorStrategy()), HistoricalFilter.IDENTITY_FILTER);
        for (int serverNumber : segmentServers) {
            final DruidServerMetadata serverMetadata = SERVERS.get(serverNumber);
            final DruidServer server = new DruidServer(serverMetadata);
            serverSelector.addServerAndUpdateSegment(new QueryableDruidServer(server, null), dataSegment);
        }
        timeline.add(dataSegment.getInterval(), dataSegment.getVersion(), dataSegment.getShardSpec().createChunk(serverSelector));
    }
