public void testFetchRowsFromServer() throws ExecutionException, InterruptedException {
    ScanResultValue scanResultValue = new ScanResultValue(null, ImmutableList.of(), ImmutableList.of(ImmutableList.of("abc", "123"), ImmutableList.of("ghi", "456"), ImmutableList.of("xyz", "789")));
