public void testOneSegmentRelocated() throws ExecutionException, InterruptedException {
    ScanResultValue scanResultValue1 = new ScanResultValue(null, ImmutableList.of(), ImmutableList.of(ImmutableList.of("abc", "123"), ImmutableList.of("ghi", "456")));
    doAnswer(invocation -> {
        ResponseContext responseContext = invocation.getArgument(1);
        responseContext.addMissingSegments(ImmutableList.of(IndexerDataServerQueryHandler.toSegmentDescriptorWithFullInterval(SEGMENT_2)));
        return Futures.immediateFuture(Sequences.simple(ImmutableList.of(scanResultValue1)));
    }).when(dataServerClient1).run(any(), any(), any(), any());
    ScanResultValue scanResultValue2 = new ScanResultValue(null, ImmutableList.of(), ImmutableList.of(ImmutableList.of("pit", "579"), ImmutableList.of("xyz", "897")));
    doReturn(Futures.immediateFuture(Sequences.simple(ImmutableList.of(scanResultValue2)))).when(dataServerClient2).run(any(), any(), any(), any());
    doReturn(Futures.immediateFuture(Boolean.FALSE)).when(coordinatorClient).isHandoffComplete(DATASOURCE1, IndexerDataServerQueryHandler.toSegmentDescriptorWithFullInterval(SEGMENT_2));
    doReturn(ImmutableList.of(new ImmutableSegmentLoadInfo(DataSegment.builder().interval(SEGMENT_2.getInterval()).version(SEGMENT_2.getVersion()).shardSpec(new NumberedShardSpec(SEGMENT_2.getPartitionNumber(), SEGMENT_2.getPartitionNumber())).dataSource(DATASOURCE1).size(1).build(), ImmutableSet.of(DRUID_SERVER_2)))).when(coordinatorClient).fetchServerViewSegments(DATASOURCE1, ImmutableList.of(SEGMENT_2.getFullInterval()));
    DataServerQueryResult<Object[]> dataServerQueryResult = target.fetchRowsFromDataServer(query, ScanQueryFrameProcessor.SCAN_RESULT_VALUE_TYPE, ScanQueryFrameProcessor::mappingFunction, Closer.create()).get();
    Assert.assertTrue(dataServerQueryResult.getHandedOffSegments().getDescriptors().isEmpty());
    Yielder<Object[]> yielder1 = dataServerQueryResult.getResultsYielders().get(0);
    ((List<List<Object>>) scanResultValue1.getEvents()).forEach(event -> {
        Assert.assertArrayEquals(event.toArray(), yielder1.get());
        yielder1.next(null);
    });
    Yielder<Object[]> yielder2 = dataServerQueryResult.getResultsYielders().get(1);
    ((List<List<Object>>) scanResultValue2.getEvents()).forEach(event -> {
        Assert.assertArrayEquals(event.toArray(), yielder2.get());
        yielder2.next(null);
    });
}

