@Test
void testQueryRunner() {
    RowSignature sig = RowSignature.builder().add("a", ColumnType.STRING).add("b", ColumnType.STRING).build();
    TestScanQuery scan1 = new TestScanQuery("foo", sig).appendRow("a", "a").appendRow("a", "b");
    TestScanQuery scan2 = new TestScanQuery("bar", sig).appendRow("x", "x").appendRow("x", "y");
    UnionQuery query = new UnionQuery(ImmutableList.of(scan1.query, scan2.query));
    query = (UnionQuery) serializedAsRows(query);
    QuerySegmentWalker walker = Mockito.mock(QuerySegmentWalker.class);
    Mockito.when(walker.getQueryRunnerForIntervals(argThat(scan1::matchQuery), any())).thenReturn((q, ctx) -> (Sequence) scan1.makeResultSequence());
    Mockito.when(walker.getQueryRunnerForIntervals(argThat(scan2::matchQuery), any())).thenReturn((q, ctx) -> (Sequence) scan2.makeResultSequence());
    QueryRunner<Object> unionRunner = queryLogic.entryPoint(query, walker);
    Sequence results = unionRunner.run(QueryPlus.wrap(query), null);
    QueryToolChestTestHelper.assertArrayResultsEquals(Sequences.concat(scan1.makeResultsAsArrays(), scan2.makeResultsAsArrays()).toList(), results);
}

