@Test
public void testRunRetryForRetryableException() {
    String inactiveDatasourceName = "inactive_datasource";
    DataSourceCompactionConfig inactiveDatasourceConfig = InlineSchemaDataSourceCompactionConfig.builder().forDataSource(inactiveDatasourceName).withInputSegmentSizeBytes(500L).withSkipOffsetFromLatest(new Period(3600)).withGranularitySpec(new UserCompactionTaskGranularityConfig(Granularities.HOUR, null, null)).withTaskContext(ImmutableMap.of("key", "val")).build();
    DruidCompactionConfig originalCurrentConfig = DruidCompactionConfig.empty().withDatasourceConfigs(ImmutableList.of(inactiveDatasourceConfig));
    byte[] originalCurrentConfigBytes = { 1, 2, 3 };
    Mockito.when(mockConnector.lookup(ArgumentMatchers.anyString(), ArgumentMatchers.eq("name"), ArgumentMatchers.eq("payload"), ArgumentMatchers.eq(DruidCompactionConfig.CONFIG_KEY))).thenReturn(originalCurrentConfigBytes);
    Mockito.when(mockJacksonConfigManager.convertByteToConfig(ArgumentMatchers.eq(originalCurrentConfigBytes), ArgumentMatchers.eq(DruidCompactionConfig.class), ArgumentMatchers.eq(DruidCompactionConfig.empty()))).thenReturn(originalCurrentConfig);
    Mockito.when(mockStorageCoordinator.retrieveAllDatasourceNames()).thenReturn(ImmutableSet.of());
    Mockito.when(mockJacksonConfigManager.set(ArgumentMatchers.eq(DruidCompactionConfig.CONFIG_KEY), ArgumentMatchers.any(byte[].class), ArgumentMatchers.any(DruidCompactionConfig.class), ArgumentMatchers.any())).thenReturn(// Return fail result with RetryableException the first three calls to updated set
    ConfigManager.SetResult.retryableFailure(new Exception()), ConfigManager.SetResult.retryableFailure(new Exception()), ConfigManager.SetResult.retryableFailure(new Exception()), // Return success ok on the fourth call to set updated config
    ConfigManager.SetResult.ok());
    final MetadataCleanupConfig config = new MetadataCleanupConfig(true, new Duration("PT6S"), null);
    killCompactionConfig = new KillCompactionConfig(config, mockStorageCoordinator, coordinatorConfigManager);
    killCompactionConfig.run(mockDruidCoordinatorRuntimeParams);
    // Verify that 1 config has been deleted
    Assert.assertEquals(1, runStats.get(Stats.Kill.COMPACTION_CONFIGS));
    // Should call convertByteToConfig and lookup (to refresh current compaction config) four times due to RetryableException when failed
    Mockito.verify(mockJacksonConfigManager, Mockito.times(4)).convertByteToConfig(ArgumentMatchers.eq(originalCurrentConfigBytes), ArgumentMatchers.eq(DruidCompactionConfig.class), ArgumentMatchers.eq(DruidCompactionConfig.empty()));
    Mockito.verify(mockConnector, Mockito.times(4)).lookup(ArgumentMatchers.anyString(), ArgumentMatchers.eq("name"), ArgumentMatchers.eq("payload"), ArgumentMatchers.eq(DruidCompactionConfig.CONFIG_KEY));
    // Should call set (to try set new updated compaction config) four times due to RetryableException when failed
    Mockito.verify(mockJacksonConfigManager, Mockito.times(4)).set(ArgumentMatchers.eq(DruidCompactionConfig.CONFIG_KEY), ArgumentMatchers.any(byte[].class), ArgumentMatchers.any(DruidCompactionConfig.class), ArgumentMatchers.any());
    Mockito.verifyNoMoreInteractions(mockJacksonConfigManager);
    // Should call retrieveAllDataSourceNames four times due to RetryableException when failed
    Mockito.verify(mockStorageCoordinator, Mockito.times(4)).retrieveAllDatasourceNames();
    Mockito.verifyNoMoreInteractions(mockStorageCoordinator);
}

