    Mockito.when(mockStorageCoordinator.retrieveAllDatasourceNames()).thenReturn(ImmutableSet.of());
    Mockito.when(mockJacksonConfigManager.set(ArgumentMatchers.eq(DruidCompactionConfig.CONFIG_KEY), ArgumentMatchers.any(byte[].class), ArgumentMatchers.any(DruidCompactionConfig.class), ArgumentMatchers.any())).thenReturn(// Return fail result with RetryableException the first three calls to updated set
    ConfigManager.SetResult.retryableFailure(new Exception()), ConfigManager.SetResult.retryableFailure(new Exception()), ConfigManager.SetResult.retryableFailure(new Exception()), // Return success ok on the fourth call to set updated config
    ConfigManager.SetResult.ok());
    final MetadataCleanupConfig config = new MetadataCleanupConfig(true, new Duration("PT6S"), null);
    killCompactionConfig = new KillCompactionConfig(config, mockStorageCoordinator, coordinatorConfigManager);
