@Test
public void testKillUnreferencedSchema() {
    List<DateTime> dateTimes = new ArrayList<>();
    DateTime now = DateTimes.nowUtc();
    dateTimes.add(now);
    dateTimes.add(now.plusMinutes(61));
    dateTimes.add(now.plusMinutes(6 * 60 + 1));
    final MetadataCleanupConfig cleanupConfig = new MetadataCleanupConfig(true, Period.parse("PT1H").toStandardDuration(), Period.parse("PT6H").toStandardDuration());
    KillUnreferencedSegmentSchema duty = new TestKillUnreferencedSegmentSchemas(cleanupConfig, segmentSchemaManager, dateTimes);
    Set<DataSegment> segments = new HashSet<>();
    List<SegmentSchemaManager.SegmentSchemaMetadataPlus> schemaMetadataPluses = new ArrayList<>();
    RowSignature rowSignature = RowSignature.builder().add("c1", ColumnType.FLOAT).build();
    SchemaPayload schemaPayload = new SchemaPayload(rowSignature);
    SchemaPayloadPlus schemaMetadata = new SchemaPayloadPlus(schemaPayload, (long) 1);
    DataSegment segment1 = new DataSegment("foo", Intervals.of("2023-01-01/2023-01-02"), "2023-01-01", ImmutableMap.of("path", "a-1"), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
    DataSegment segment2 = new DataSegment("foo", Intervals.of("2023-01-02/2023-01-03"), "2023-01-02", ImmutableMap.of("path", "a-1"), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
    segments.add(segment1);
    segments.add(segment2);
    String fingerprint = fingerprintGenerator.generateFingerprint(schemaPayload, segment1.getDataSource(), CentralizedDatasourceSchemaConfig.SCHEMA_VERSION);
    SegmentSchemaManager.SegmentSchemaMetadataPlus plus1 = new SegmentSchemaManager.SegmentSchemaMetadataPlus(segment1.getId(), fingerprint, schemaMetadata);
    schemaMetadataPluses.add(plus1);
    SegmentSchemaManager.SegmentSchemaMetadataPlus plus2 = new SegmentSchemaManager.SegmentSchemaMetadataPlus(segment2.getId(), fingerprint, schemaMetadata);
    schemaMetadataPluses.add(plus2);
    segmentSchemaTestUtils.insertUsedSegments(segments, Collections.emptyMap());
    segmentSchemaManager.persistSchemaAndUpdateSegmentsTable("foo", schemaMetadataPluses, CentralizedDatasourceSchemaConfig.SCHEMA_VERSION);
    // delete segment1
    deleteSegment(schemaMetadataPluses.get(0).getSegmentId());
    // this call should do nothing
    duty.run(mockDruidCoordinatorRuntimeParams);
    Assert.assertEquals(Boolean.TRUE, getSchemaUsedStatus(fingerprint));
    // delete segment2
    deleteSegment(schemaMetadataPluses.get(1).getSegmentId());
    // this call should mark the schema unused
    duty.run(mockDruidCoordinatorRuntimeParams);
    Assert.assertEquals(Boolean.FALSE, getSchemaUsedStatus(fingerprint));
    // this call should delete the schema
    duty.run(mockDruidCoordinatorRuntimeParams);
    Assert.assertNull(getSchemaUsedStatus(fingerprint));
}

