@Test
public void testKillUnreferencedSchema_repair() {
    List<DateTime> dateTimes = new ArrayList<>();
    DateTime now = DateTimes.nowUtc();
    dateTimes.add(now);
    dateTimes.add(now.plusMinutes(61));
    MetadataCleanupConfig cleanupConfig = new MetadataCleanupConfig(true, Period.parse("PT1H").toStandardDuration(), Period.parse("PT6H").toStandardDuration());
    KillUnreferencedSegmentSchema duty = new TestKillUnreferencedSegmentSchemas(cleanupConfig, segmentSchemaManager, dateTimes);
    RowSignature rowSignature = RowSignature.builder().add("c1", ColumnType.FLOAT).build();
    SchemaPayload schemaPayload = new SchemaPayload(rowSignature);
    String fingerprint = fingerprintGenerator.generateFingerprint(schemaPayload, "foo", CentralizedDatasourceSchemaConfig.SCHEMA_VERSION);
    inHandle(handle -> {
        segmentSchemaManager.persistSegmentSchema(handle, "foo", CentralizedDatasourceSchemaConfig.SCHEMA_VERSION, Collections.singletonMap(fingerprint, schemaPayload), DateTimes.nowUtc());
        return null;
    });
    Assert.assertEquals(Boolean.TRUE, getSchemaUsedStatus(fingerprint));
    // this call should mark the schema as unused
    duty.run(mockDruidCoordinatorRuntimeParams);
    Assert.assertEquals(Boolean.FALSE, getSchemaUsedStatus(fingerprint));
    // associate a segment to the schema
    DataSegment segment1 = new DataSegment("foo", Intervals.of("2023-01-02/2023-01-03"), "2023-01-02", ImmutableMap.of("path", "a-1"), ImmutableList.of("dim1"), ImmutableList.of("m1"), new LinearShardSpec(0), 9, 100);
    segmentSchemaTestUtils.insertUsedSegments(Collections.singleton(segment1), Collections.emptyMap());
    inHandle(handle -> handle.createStatement(StringUtils.format("UPDATE %s SET schema_fingerprint = '%s', num_rows = 100 WHERE id = '%s'", tablesConfig.getSegmentsTable(), fingerprint, segment1.getId().toString())).execute());
    // this call should make the schema used
    duty.run(mockDruidCoordinatorRuntimeParams);
    Assert.assertEquals(Boolean.TRUE, getSchemaUsedStatus(fingerprint));
}

