@Test
public void testGetAllSegmentsIncludingRealtime() {
    CoordinatorSegmentMetadataCache coordinatorSegmentMetadataCache = Mockito.mock(CoordinatorSegmentMetadataCache.class);
    String dataSource2 = "datasource2";
    DataSegment[] realTimeSegments = CreateDataSegments.ofDatasource(dataSource2).forIntervals(3, Granularities.DAY).withNumPartitions(2).eachOfSizeInMb(500).toArray(new DataSegment[0]);
    Mockito.doReturn(null).when(coordinator).getReplicationFactor(realTimeSegments[0].getId());
    Mockito.doReturn(null).when(coordinator).getReplicationFactor(realTimeSegments[1].getId());
    Map<SegmentId, AvailableSegmentMetadata> availableSegments = new LinkedHashMap<>();
    availableSegments.put(segments[0].getId(), AvailableSegmentMetadata.builder(segments[0], 0L, Collections.emptySet(), null, 20L).build());
    availableSegments.put(segments[1].getId(), AvailableSegmentMetadata.builder(segments[1], 0L, Collections.emptySet(), null, 30L).build());
    availableSegments.put(segments[1].getId(), AvailableSegmentMetadata.builder(segments[1], 0L, Collections.emptySet(), null, 30L).build());
    availableSegments.put(realTimeSegments[0].getId(), AvailableSegmentMetadata.builder(realTimeSegments[0], 1L, Collections.emptySet(), null, 10L).build());
    availableSegments.put(realTimeSegments[1].getId(), AvailableSegmentMetadata.builder(realTimeSegments[1], 1L, Collections.emptySet(), null, 40L).build());
    Mockito.doReturn(availableSegments).when(coordinatorSegmentMetadataCache).getSegmentMetadataSnapshot();
    Mockito.doReturn(availableSegments.get(segments[0].getId())).when(coordinatorSegmentMetadataCache).getAvailableSegmentMetadata(DATASOURCE1, segments[0].getId());
    Mockito.doReturn(availableSegments.get(segments[1].getId())).when(coordinatorSegmentMetadataCache).getAvailableSegmentMetadata(DATASOURCE1, segments[1].getId());
    metadataResource = new MetadataResource(segmentsMetadataManager, storageCoordinator, AuthTestUtils.TEST_AUTHORIZER_MAPPER, coordinator, coordinatorSegmentMetadataCache);
    Response response = metadataResource.getAllUsedSegments(request, null, "includeOvershadowedStatus", "includeRealtimeSegments");
    final List<SegmentStatusInCluster> resultList = extractResponseList(response);
    Assert.assertEquals(resultList.size(), 6);
    Map<SegmentId, SegmentStatusInCluster> resultMap = resultList.stream().collect(Collectors.toMap(segmentStatus -> segmentStatus.getDataSegment().getId(), Function.identity()));
    Assert.assertEquals(new SegmentStatusInCluster(segments[0], false, 2, 20L, false), resultMap.get(segments[0].getId()));
    Assert.assertEquals(new SegmentStatusInCluster(segments[1], false, null, 30L, false), resultMap.get(segments[1].getId()));
    Assert.assertEquals(new SegmentStatusInCluster(segments[2], false, 1, null, false), resultMap.get(segments[2].getId()));
    // Replication factor should be 0 as the segment is overshadowed
    Assert.assertEquals(new SegmentStatusInCluster(segments[3], true, 0, null, false), resultMap.get(segments[3].getId()));
    Assert.assertEquals(new SegmentStatusInCluster(realTimeSegments[0], false, null, 10L, true), resultMap.get(realTimeSegments[0].getId()));
    Assert.assertEquals(new SegmentStatusInCluster(realTimeSegments[1], false, null, 40L, true), resultMap.get(realTimeSegments[1].getId()));
}

