@Test
public void testMetricsEmittedWithErrorStatusCodeButNoResultException() {
    final TimeseriesQuery query = Druids.newTimeseriesQueryBuilder().dataSource("foo").intervals("2000/P1D").granularity(Granularities.ALL).context(ImmutableMap.of("queryId", "test-query-504")).build();
