    Mockito.when(requestMock.getAttribute("org.apache.druid.proxy.sqlQuery")).thenReturn(null);
    Mockito.when(requestMock.getRemoteAddr()).thenReturn("127.0.0.1");
    Mockito.when(requestMock.getAttribute(AuthConfig.DRUID_AUTHENTICATION_RESULT)).thenReturn(new AuthenticationResult("testUser", "basic", "basic", null));
    final Request proxyRequestMock = Mockito.mock(Request.class);
    final Response responseMock = Mockito.mock(Response.class);
    // Gateway Timeout
    Mockito.when(responseMock.getStatus()).thenReturn(504);
    Mockito.when(responseMock.getHeaders()).thenReturn(HttpFields.build());
    Mockito.when(responseMock.getRequest()).thenReturn(proxyRequestMock);
    final Result result = new Result(proxyRequestMock, responseMock) {

        @Override
        public Throwable getFailure() {
            // No exception thrown
            return null;
        }
    };
    final StubServiceEmitter stubServiceEmitter = StubServiceEmitter.createStarted();
    final AsyncQueryForwardingServlet servlet = new AsyncQueryForwardingServlet(new MapQueryToolChestWarehouse(ImmutableMap.of()), TestHelper.makeJsonMapper(), TestHelper.makeSmileMapper(), null, null, null, stubServiceEmitter, NoopRequestLogger.instance(), new DefaultGenericQueryMetricsFactory(), new AuthenticatorMapper(ImmutableMap.of()), new Properties(), new ServerConfig());
    try {
        servlet.newProxyResponseListener(requestMock, null).onComplete(result);
    } catch (NullPointerException ignored) {
    }
    stubServiceEmitter.verifyEmitted("query/time", 1);
    Assert.assertEquals("test-query-504", stubServiceEmitter.getEvents().get(0).toMap().get("id"));
    Assert.assertEquals(504, stubServiceEmitter.getMetricEvents("query/time").get(0).toMap().get(DruidMetrics.STATUS_CODE));
    Assert.assertEquals("false", stubServiceEmitter.getMetricEvents("query/time").get(0).toMap().get("success"));
}

