    final List<SegmentStatusInCluster> expectedSegments = CreateDataSegments.ofDatasource(TestDataSource.WIKI).withNumPartitions(10).eachOfSizeInMb(100).stream().map(s -> new SegmentStatusInCluster(s, false, 1, 100L, false)).toList();
    Mockito.when(coordinatorClient.fetchAllUsedSegmentsWithOvershadowedStatus(ArgumentMatchers.eq(null), ArgumentMatchers.eq(true))).thenReturn(Futures.immediateFuture(CloseableIterators.withEmptyBaggage(expectedSegments.iterator())));
